      "topic": "scope",
      "statement": "The fixed entry reads PNG bytes sequentially: it checks the signature, creates read structures, calls png_read_info and png_read_update_info, then calls png_start_read_image before looping over png_read_row.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 67, "end_line": 85, "role": "primary", "dependency_reason": ""},
