      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On both supplied source versions, png_start_read_image calls png_read_start_row when PNG_FLAG_ROW_INIT is clear; when it is set, the function reports a duplicate call through png_app_error.",
      "evidence": [
        {"unit_id": "u-328bde2dc5a686c0958f", "start_line": 297, "end_line": 312, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-02b6226984a9ddec355c", "start_line": 297, "end_line": 312, "role": "primary", "dependency_reason": ""}
      ],
