        {"unit_id": "u-02b6226984a9ddec355c", "start_line": 302, "end_line": 305, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e722f9e70d24b0238d2b", "start_line": 805, "end_line": 855, "role": "dependency", "dependency_reason": "Shows the separate test's sequential reading call order."},
